{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "required": [
    "version",
    "maximumItems",
    "maximumCopyBytes",
    "maximumDepth",
    "maximumTurns",
    "cases"
  ],
  "additionalProperties": false,
  "properties": {
    "version": {
      "const": 1
    },
    "maximumItems": {
      "const": 1
    },
    "maximumCopyBytes": {
      "const": 3
    },
    "maximumDepth": {
      "const": 64
    },
    "maximumTurns": {
      "const": 100000
    },
    "cases": {
      "const": [
        {
          "kind": "null",
          "value": null,
          "payloadBytes": 0
        },
        {
          "kind": "bool",
          "value": true,
          "payloadBytes": 1
        },
        {
          "kind": "uint",
          "value": 42,
          "payloadBytes": 8
        },
        {
          "kind": "int",
          "value": -42,
          "payloadBytes": 8
        },
        {
          "kind": "float",
          "value": 1.25,
          "payloadBytes": 8
        },
        {
          "kind": "text",
          "value": "groß🧬",
          "payloadBytes": 9
        },
        {
          "kind": "bytes",
          "value": [
            0,
            127,
            255
          ],
          "payloadBytes": 3
        },
        {
          "kind": "array",
          "value": [
            true,
            "ö",
            [
              42,
              null
            ]
          ],
          "payloadBytes": 11
        },
        {
          "kind": "object",
          "value": {
            "a": [
              false,
              "🧬"
            ],
            "ö": -7
          },
          "payloadBytes": 16
        },
        {
          "kind": "reserved-text",
          "value": "",
          "capacity": 128,
          "payloadBytes": 0
        },
        {
          "kind": "reserved-bytes",
          "value": [],
          "capacity": 17,
          "payloadBytes": 0
        },
        {
          "kind": "reserved-array",
          "value": [],
          "capacity": 5,
          "payloadBytes": 0
        },
        {
          "kind": "reserved-object",
          "value": {},
          "capacity": 5,
          "payloadBytes": 0
        }
      ]
    }
  }
}
